SELECT AVG(CAST(metric_0001 AS DOUBLE PRECISION)) AS avg_metric_0001, AVG(CAST(metric_0556 AS DOUBLE PRECISION)) AS avg_metric_0556, AVG(CAST(metric_1111 AS DOUBLE PRECISION)) AS avg_metric_1111, AVG(CAST(metric_1667 AS DOUBLE PRECISION)) AS avg_metric_1667, AVG(CAST(metric_2222 AS DOUBLE PRECISION)) AS avg_metric_2222, AVG(CAST(metric_2778 AS DOUBLE PRECISION)) AS avg_metric_2778, AVG(CAST(metric_3333 AS DOUBLE PRECISION)) AS avg_metric_3333, AVG(CAST(metric_3889 AS DOUBLE PRECISION)) AS avg_metric_3889, AVG(CAST(metric_4444 AS DOUBLE PRECISION)) AS avg_metric_4444, AVG(CAST(metric_5000 AS DOUBLE PRECISION)) AS avg_metric_5000 FROM wide5000 WHERE time >= '2024-12-22' AND time < '2025-01-01'
